/// Reimplements C++ `std::stof` semantics: leading whitespace is skipped,
/// the longest valid float prefix is parsed (trailing garbage ignored),
/// `inf`/`infinity`/`nan` are accepted, and invalid or out-of-range input
/// aborts the process the way an uncaught C++ exception does.

pub fn stof(s: &str) -> f32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }
    let start = i;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        i += 1;
    }

    let lower = s[i..].to_ascii_lowercase();
    if lower.starts_with("infinity") || lower.starts_with("inf") {
        return if s.as_bytes()[start] == b'-' {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        };
    }
    if lower.starts_with("nan") {
        return f32::NAN;
    }

    let mut j = i;
    let mut saw_digit = false;
    while j < bytes.len() && bytes[j].is_ascii_digit() {
        j += 1;
        saw_digit = true;
    }
    if j < bytes.len() && bytes[j] == b'.' {
        j += 1;
        while j < bytes.len() && bytes[j].is_ascii_digit() {
            j += 1;
            saw_digit = true;
        }
    }
    if !saw_digit {
        invalid_argument();
    }
    let mut end = j;
    if j < bytes.len() && (bytes[j] == b'e' || bytes[j] == b'E') {
        let mut k = j + 1;
        if k < bytes.len() && (bytes[k] == b'+' || bytes[k] == b'-') {
            k += 1;
        }
        let digit_start = k;
        while k < bytes.len() && bytes[k].is_ascii_digit() {
            k += 1;
        }
        if k > digit_start {
            end = k;
        }
    }

    let v: f32 = match s[start..end].parse() {
        Ok(v) => v,
        Err(_) => invalid_argument(),
    };
    // strtof sets ERANGE on overflow (inf) and underflow (subnormal/zero
    // from a nonzero literal), which makes std::stof throw out_of_range.
    if v.is_infinite() {
        out_of_range();
    }
    v
}

fn invalid_argument() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::invalid_argument'");
    eprintln!("  what():  stof");
    std::process::abort();
}

fn out_of_range() -> ! {
    eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
    eprintln!("  what():  stof");
    std::process::abort();
}

